mapper.select:
SELECT 
FROM TBL_COMPLIANCE_RULE
WHERE DELETE_FLAG = 0

    AND RULE_CODE LIKE CONCAT('%', #{ruleCode}, '%')


    AND RULE_NAME LIKE CONCAT('%', #{ruleName}, '%')


    AND RULE_TYPE = #{ruleType}


    AND AUTHORITY_ID = #{authorityId}


    AND SEVERITY_LEVEL = #{severityLevel}


    AND IS_ENABLED = #{isEnabled}


    AND COMPANY_ID = #{companyId}

ORDER BY CREATED_TIME DESC

mapper.update:
UPDATE TBL_COMPLIANCE_RULE
SET IS_ENABLED = #{isEnabled}, UPDATED_TIME = SYSDATE
WHERE RULE_ID = #{ruleId}
